  IF projection IS DISTINCT FROM CASE max_rank WHEN 2 THEN 'level_2' WHEN 1 THEN 'level_1' ELSE 'none' END THEN
    RAISE EXCEPTION 'Priority projection mismatch' USING ERRCODE = '23514';
  END IF;
